class Solution {
  public long distributeCandies(int n, int limit) {
    long answer = 0;
    for (int excluded = 0; excluded <= 3; excluded++) {
      long ways = chooseTwo(n - excluded * (limit + 1));
      answer += (excluded % 2 == 0 ? 1 : -1) * binomial(3, excluded) * ways;
    }
    return answer;
  }

  private long chooseTwo(long sum) {
    return sum < 0 ? 0 : (sum + 1) * (sum + 2) / 2;
  }

  private long binomial(int n, int k) {
    if (k == 0 || k == n) return 1;
    if (k == 1 || k == n - 1) return n;
    return 3;
  }
}
